import{_ as e,c as a,a2 as r,o}from"./chunks/framework.oYgP5hCw.js";const u=JSON.parse('{"title":"Zlattice建链","description":"","frontmatter":{},"headers":[],"relativePath":"source/index.md","filePath":"source/index.md","lastUpdated":1736405478000}'),p={name:"source/index.md"};function s(n,t,h,i,c,l){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="zlattice建链" tabindex="-1">Zlattice建链 <a class="header-anchor" href="#zlattice建链" aria-label="Permalink to &quot;Zlattice建链&quot;">​</a></h1><h3 id="_1、增加配置文件config-toml和genesis-json" tabindex="-1">1、增加配置文件config.toml和genesis.json <a class="header-anchor" href="#_1、增加配置文件config-toml和genesis-json" aria-label="Permalink to &quot;1、增加配置文件config.toml和genesis.json&quot;">​</a></h3><p>将genesis.json.exmaple和config.toml.exmaple分别拷贝一份，将文件名改为genesis.json和config.toml</p><p><a href="https://imgtu.com/i/hyCMhF" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyCMhF.png" alt="hyCMhF.png"></a></p><h3 id="_2、创建saint账户-saint账户是专门作为见证账户" tabindex="-1">2、创建saint账户，saint账户是专门作为见证账户 <a class="header-anchor" href="#_2、创建saint账户-saint账户是专门作为见证账户" aria-label="Permalink to &quot;2、创建saint账户，saint账户是专门作为见证账户&quot;">​</a></h3><p><a href="https://imgtu.com/i/hyP0aV" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyP0aV.png" alt="hyP0aV.png"></a></p><p><a href="https://imgtu.com/i/hyi6Ff" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyi6Ff.png" alt="hyi6Ff.png"></a></p><p><a href="https://imgtu.com/i/hyFuAP" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyFuAP.png" alt="hyFuAP.png"></a></p><p>首次run saint后项目目录中生成saintkey文件</p><p>已有saintkey文件后，run saint会选择更新saintkey内容，也就是更新saint账户信息。</p><p><a href="https://imgtu.com/i/hyFyu9" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyFyu9.png" alt="hyFyu9.png"></a></p><h3 id="_3、更改genesis-json和config-toml中的配置" tabindex="-1">3、更改genesis.json和config.toml中的配置 <a class="header-anchor" href="#_3、更改genesis-json和config-toml中的配置" aria-label="Permalink to &quot;3、更改genesis.json和config.toml中的配置&quot;">​</a></h3><p>更改genesis.json文件中的&quot;latcSaints&quot;和&quot;preacher&quot;</p><p><a href="https://imgtu.com/i/hykBIP" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hykBIP.png" alt="hykBIP.png"></a></p><p>更改config.toml中的Host项为自己的本机ip，其他项可不变。</p><p>注意：若本机ip非固定ip，每次启动链前，需要检查ip是否变化，作相应更改</p><p><a href="https://imgtu.com/i/hyA9zD" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyA9zD.png" alt="hyA9zD.png"></a></p><h3 id="_4、配置start命令-启动链" tabindex="-1">4、配置start命令，启动链 <a class="header-anchor" href="#_4、配置start命令-启动链" aria-label="Permalink to &quot;4、配置start命令，启动链&quot;">​</a></h3><p>同saint命令配置，配置start</p><p><a href="https://imgtu.com/i/hyVIit" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyVIit.png" alt="hyVIit.png"></a></p><p><a href="https://imgtu.com/i/hyZI0J" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyZI0J.png" alt="hyZI0J.png"></a></p><p>go build配置完start，开始run start</p><p><a href="https://imgtu.com/i/hyeuAs" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyeuAs.png" alt="hyeuAs.png"></a></p><p>若进入console界面，且有出块信息，则链创建成功，如下：</p><p><a href="https://imgtu.com/i/hyeTKS" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyeTKS.png" alt="hyeTKS.png"></a></p><p>此时，本地链已经创建成功，但链上只有saint账户，若要测试交易，还可以创建普通账户，见操作5</p><h3 id="_5、创建普通账户" tabindex="-1">5、创建普通账户 <a class="header-anchor" href="#_5、创建普通账户" aria-label="Permalink to &quot;5、创建普通账户&quot;">​</a></h3><p>流程如图：</p><p><img src="https://z3.ax1x.com/2021/09/03/hyurvV.png" alt="hyurvV.png"></p><p><a href="https://imgtu.com/i/hyurvV" target="_blank" rel="noreferrer"></a></p><p><a href="https://imgtu.com/i/hyucbF" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyucbF.png" alt="hyucbF.png"></a></p><p><a href="https://imgtu.com/i/hyuIv6" target="_blank" rel="noreferrer"><img src="https://z3.ax1x.com/2021/09/03/hyuIv6.png" alt="hyuIv6.png"></a></p><h3 id="可选-使用couchdb替代leveldb存储链数据的方法" tabindex="-1">可选：使用CouchDB替代LevelDB存储链数据的方法 <a class="header-anchor" href="#可选-使用couchdb替代leveldb存储链数据的方法" aria-label="Permalink to &quot;可选：使用CouchDB替代LevelDB存储链数据的方法&quot;">​</a></h3><h4 id="step1-完成上述配置后-在config-toml文件中解除下面四行的注释" tabindex="-1">Step1: 完成上述配置后，在config.toml文件中<strong>解除</strong>下面四行的注释 <a class="header-anchor" href="#step1-完成上述配置后-在config-toml文件中解除下面四行的注释" aria-label="Permalink to &quot;Step1: 完成上述配置后，在config.toml文件中**解除**下面四行的注释&quot;">​</a></h4><p><code>CouchDB_Enable = true # false 则使用默认leveldb，true则使用CouchDB</code></p><p><code>CouchDB_Address= &quot;127.0.0.1:5984&quot; #CouchDB连接URL</code></p><p><code>CouchDB_Username= &quot;admin&quot; #CouchDB用户名</code></p><p><code>CouchDB_Password= &quot;password&quot; #CouchDB密码</code></p><h4 id="step2-安装couchdb" tabindex="-1">Step2: 安装CouchDB <a class="header-anchor" href="#step2-安装couchdb" aria-label="Permalink to &quot;Step2: 安装CouchDB&quot;">​</a></h4><p>推荐使用docker一键部署，因为跨设备网络通讯存在不稳定性，强烈建议CouchDB和晶格链在<strong>同一台机器</strong>上部署！</p><p><code>sudo docker run -p 5984:5984 -e COUCHDB_USER=admin -e COUCHDB_PASSWORD=password -d couchdb</code></p><h4 id="step3-创建数据库" tabindex="-1">Step3: 创建数据库 <a class="header-anchor" href="#step3-创建数据库" aria-label="Permalink to &quot;Step3: 创建数据库&quot;">​</a></h4><p>docker下的CouchDB容器启动之后，浏览器打开</p><p>127.0.0.1（根据情况调整，这个地址是docker宿主机地址）:5984/_utils/</p><p><img src="http://home.ustc.edu.cn/~zyma/pics/1.jpg" alt=""></p><p>用户名+密码在docker启动时已经指定：admin/password</p><p>登录后，按照下图选择 Create Database</p><p><img src="http://home.ustc.edu.cn/~zyma/pics/2.jpg" alt=""></p><p>输入数据库名latc，点击Create即可</p><p><img src="http://home.ustc.edu.cn/~zyma/pics/3.jpg" alt=""></p><h4 id="step4-启动晶格链" tabindex="-1">Step4: 启动晶格链 <a class="header-anchor" href="#step4-启动晶格链" aria-label="Permalink to &quot;Step4: 启动晶格链&quot;">​</a></h4><p>根据上文run start即可启动CouchDB模式下的晶格链。</p>',52)]))}const m=e(p,[["render",s]]);export{u as __pageData,m as default};
